export function riverMap(after=false,id='main',animated=true){return `<svg class="river-map ${after?'after':'before'} ${animated?'animated':''}" viewBox="0 0 1000 540" role="img" aria-labelledby="${id}-title ${id}-desc"><title id="${id}-title">${after?'After 1900: away from Lake Michigan':'Before 1900: toward Lake Michigan'}</title><desc id="${id}-desc">Schematic map. ${after?'Water travels west from Lake Michigan, then southwest through the Chicago Sanitary and Ship Canal toward the Des Plaines River.':'The Chicago River flows east into Lake Michigan. The future Sanitary and Ship Canal route is shown as a dotted line.'} The fountain’s present-day location is marked on the north bank.</desc><defs><pattern id="${id}-grid" width="46" height="46" patternUnits="userSpaceOnUse"><path d="M46 0H0V46" fill="none" stroke="#d3d8cd" stroke-width="1"/></pattern><marker id="${id}-arrow" viewBox="0 0 12 12" refX="6" refY="6" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M2 2L10 6L2 10" fill="none" stroke="#f6f3e9" stroke-width="2"/></marker></defs><rect width="1000" height="540" fill="#e9eade"/><rect width="1000" height="540" fill="url(#${id}-grid)"/><path d="M770-10C750 60 774 95 750 150S795 225 766 290 774 400 750 550H1020V-10Z" fill="#82aeb0"/><path d="M750-10C730 60 754 95 730 150S775 225 746 290 754 400 730 550" fill="none" stroke="#d8ddc9" stroke-width="18"/><path d="M390-20L402 90 448 154 445 230Q445 255 478 255L778 255M445 247L445 345 356 400" fill="none" stroke="#67999c" stroke-width="26" stroke-linecap="round" stroke-linejoin="round"/><path d="M356 400L280 425 208 490 160 560" fill="none" stroke="${after?'#67999c':'#a6b5a8'}" stroke-width="${after?'26':'5'}" stroke-dasharray="${after?'none':'8 10'}" stroke-linecap="round"/><g fill="#304c50" font-family="Arial,sans-serif"><text x="817" y="170" font-size="27" font-style="italic">Lake</text><text x="800" y="204" font-size="27" font-style="italic">Michigan</text><text x="495" y="220" font-size="19">Chicago River</text><text x="490" y="350" font-size="14" letter-spacing="3">CHICAGO</text><text x="73" y="356" font-size="17">Chicago Sanitary</text><text x="73" y="380" font-size="17">and Ship Canal</text><text x="73" y="404" font-size="12">${after?'Opened in 1900':'Future route · opened in 1900'}</text><text x="74" y="501" font-size="12">${after?'Toward the Des Plaines, Illinois':'Southwest'} →</text></g><g class="flow-arrows" stroke="#f6f3e9" stroke-width="3" fill="none" marker-end="url(#${id}-arrow)">${after?'<path d="M700 255H650"/><path d="M585 255H535"/><path d="M445 290V330"/><path d="M345 404L302 419"/><path d="M246 457L212 488"/>':'<path d="M535 255H585"/><path d="M650 255H700"/><path d="M445 190V225"/><path d="M445 330V290"/>'}</g><g transform="translate(677 240)"><path d="M0 0C-4-7-14-16-14-25a14 14 0 0 1 28 0C14-16 4-7 0 0Z" fill="#e97557"/><circle cy="-24" r="4" fill="#fff9ed"/></g><text x="530" y="174" fill="#183943" font-family="Arial,sans-serif" font-size="13">Centennial Fountain</text><text x="530" y="193" fill="#536b6b" font-family="Arial,sans-serif" font-size="11">Present-day location</text><path d="M651 192L675 212" stroke="#647d79" fill="none"/><g transform="translate(938 45)" fill="#264c54"><path d="M0 23V0L-5 9M0 0L5 9" fill="none" stroke="currentColor" stroke-width="2"/><text x="-5" y="39" font-family="Arial" font-size="13">N</text></g><text x="30" y="516" font-family="Arial" font-size="11" fill="#5d7573">SCHEMATIC · NOT TO SCALE</text></svg>`}
export function initReversal(){const root=document.querySelector('[data-reversal]');if(!root)return;const map=root.querySelector('[data-map]'),buttons=[...root.querySelectorAll('[data-era]')],status=root.querySelector('[data-map-status]');buttons.forEach(b=>b.addEventListener('click',()=>{const after=b.dataset.era==='after';buttons.forEach(v=>v.setAttribute('aria-pressed',String(v===b)));map.innerHTML=riverMap(after);status.textContent=after?'After 1900 — water flows away from the lake, toward the canal.':'Before 1900 — the river carries water toward Lake Michigan.'}));const pause=root.querySelector('[data-map-pause]');pause.addEventListener('click',()=>{const paused=root.classList.toggle('map-paused');pause.setAttribute('aria-pressed',String(paused));pause.textContent=paused?'Resume arrows':'Pause arrows'})}
